UPDATE tb_completions
   SET status = #{row.status},
       completed_at = #{row.completedAt, jdbcType=TIMESTAMP_WITH_TIMEZONE},
       confirmed_by = #{row.confirmedBy, jdbcType=OTHER},
       confirmed_at = #{row.confirmedAt, jdbcType=TIMESTAMP_WITH_TIMEZONE},
       updated_at = #{row.updatedAt}
 WHERE enrollment_id = #{row.enrollmentId}
   AND status = #{expectedStatus}

UPDATE tb_completions
   SET status = #{row.status},
       completed_at = NULL,
       confirmed_by = NULL,
       confirmed_at = NULL,
       updated_at = #{row.updatedAt}
 WHERE enrollment_id = #{row.enrollmentId}
   AND status = #{expectedStatus}
